17	package com.google.zxing.oned;
18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.ChecksumException;
21	import com.google.zxing.DecodeHintType;
22	import com.google.zxing.FormatException;
23	import com.google.zxing.NotFoundException;
24	import com.google.zxing.ReaderException;
25	import com.google.zxing.Result;
26	import com.google.zxing.ResultMetadataType;
27	import com.google.zxing.ResultPoint;
28	import com.google.zxing.ResultPointCallback;
29	import com.google.zxing.common.BitArray;
30	
31	import java.util.Arrays;
32	import java.util.Map;
33	
34	/**
35	 * <p>Encapsulates functionality and implementation that is common to UPC and EAN families
36	 * of one-dimensional barcodes.</p>
37	 *
38	 * @author dswitkin@google.com (Daniel Switkin)
39	 * @author Sean Owen
40	 * @author alasdair@google.com (Alasdair Mackintosh)
41	 */
42	public abstract class UPCEANReader extends OneDReader {
43	
44	  // These two values are critical for determining how permissive the decoding will be.
45	  // We've arrived at these values through a lot of trial and error. Setting them any higher
46	  // lets false positives creep in quickly.
47	  private static final float MAX_AVG_VARIANCE = 0.48f;
48	  private static final float MAX_INDIVIDUAL_VARIANCE = 0.7f;
49	
50	  /**
51	   * Start/end guard pattern.
52	   */
53	  static final int[] START_END_PATTERN = {1, 1, 1,};
54	
55	  /**
56	   * Pattern marking the middle of a UPC/EAN pattern, separating the two halves.
57	   */
58	  static final int[] MIDDLE_PATTERN = {1, 1, 1, 1, 1};
59	  /**
60	   * end guard pattern.
61	   */
62	  static final int[] END_PATTERN = {1, 1, 1, 1, 1, 1};
63	  /**
64	   * "Odd", or "L" patterns used to encode UPC/EAN digits.
65	   */
66	  static final int[][] L_PATTERNS = {
67	      {3, 2, 1, 1}, // 0
68	      {2, 2, 2, 1}, // 1
69	      {2, 1, 2, 2}, // 2
70	      {1, 4, 1, 1}, // 3
71	      {1, 1, 3, 2}, // 4
72	      {1, 2, 3, 1}, // 5
73	      {1, 1, 1, 4}, // 6
74	      {1, 3, 1, 2}, // 7
75	      {1, 2, 1, 3}, // 8
76	      {3, 1, 1, 2}  // 9
77	  };
78	
79	  /**
80	   * As above but also including the "even", or "G" patterns used to encode UPC/EAN digits.
81	   */
82	  static final int[][] L_AND_G_PATTERNS;
83	
84	  static {
85	    L_AND_G_PATTERNS = new int[20][];
86	    System.arraycopy(L_PATTERNS, 0, L_AND_G_PATTERNS, 0, 10);
87	    for (int i = 10; i < 20; i++) {
88	      int[] widths = L_PATTERNS[i - 10];
89	      int[] reversedWidths = new int[widths.length];
90	      for (int j = 0; j < widths.length; j++) {
91	        reversedWidths[j] = widths[widths.length - j - 1];
92	      }
93	      L_AND_G_PATTERNS[i] = reversedWidths;
94	    }
95	  }
96	
97	  private final StringBuilder decodeRowStringBuffer;
98	  private final UPCEANExtensionSupport extensionReader;
99	  private final EANManufacturerOrgSupport eanManSupport;
100	
101	  protected UPCEANReader() {
102	    decodeRowStringBuffer = new StringBuilder(20);
103	    extensionReader = new UPCEANExtensionSupport();
104	    eanManSupport = new EANManufacturerOrgSupport();
105	  }
106	
107	  static int[] findStartGuardPattern(BitArray row) throws NotFoundException {
108	    boolean foundStart = false;
109	    int[] startRange = null;
110	    int nextStart = 0;
111	    int[] counters = new int[START_END_PATTERN.length];
112	    while (!foundStart) {
113	      Arrays.fill(counters, 0);
114	      startRange = findGuardPattern(row, nextStart, false, START_END_PATTERN, counters);
115	      int start = startRange[0];
116	      nextStart = startRange[1];
117	      // Make sure there is a quiet zone at least as big as the start pattern before the barcode.
118	      // If this check would run off the left edge of the image, do not accept this barcode,
119	      // as it is very likely to be a false positive.
120	      int quietStart = start - (nextStart - start);
121	      if (quietStart >= 0) {
122	        foundStart = row.isRange(quietStart, start, false);
123	      }
124	    }
125	    return startRange;
126	  }
127	
128	  @Override
129	  public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType,?> hints)
130	      throws NotFoundException, ChecksumException, FormatException {
131	    return decodeRow(rowNumber, row, findStartGuardPattern(row), hints);
132	  }
133	
134	  /**
135	   * <p>Like {@link #decodeRow(int, BitArray, Map)}, but
136	   * allows caller to inform method about where the UPC/EAN start pattern is
137	   * found. This allows this to be computed once and reused across many implementations.</p>
138	   *
139	   * @param rowNumber row index into the image
140	   * @param row encoding of the row of the barcode image
141	   * @param startGuardRange start/end column where the opening start pattern was found
142	   * @param hints optional hints that influence decoding
143	   * @return {@link Result} encapsulating the result of decoding a barcode in the row
144	   * @throws NotFoundException if no potential barcode is found
145	   * @throws ChecksumException if a potential barcode is found but does not pass its checksum
146	   * @throws FormatException if a potential barcode is found but format is invalid
147	   */
148	  public Result decodeRow(int rowNumber,
149	                          BitArray row,
150	                          int[] startGuardRange,
151	                          Map<DecodeHintType,?> hints)
152	      throws NotFoundException, ChecksumException, FormatException {
153	
154	    ResultPointCallback resultPointCallback = hints == null ? null :
155	        (ResultPointCallback) hints.get(DecodeHintType.NEED_RESULT_POINT_CALLBACK);
156	    int symbologyIdentifier = 0;
157	
158	    if (resultPointCallback != null) {
159	      resultPointCallback.foundPossibleResultPoint(new ResultPoint(
160	          (startGuardRange[0] + startGuardRange[1]) / 2.0f, rowNumber
161	      ));
162	    }
163	
164	    StringBuilder result = decodeRowStringBuffer;
165	    result.setLength(0);
166	    int endStart = decodeMiddle(row, startGuardRange, result);
167	
168	    if (resultPointCallback != null) {
169	      resultPointCallback.foundPossibleResultPoint(new ResultPoint(
170	          endStart, rowNumber
171	      ));
172	    }
173	
174	    int[] endRange = decodeEnd(row, endStart);
175	
176	    if (resultPointCallback != null) {
177	      resultPointCallback.foundPossibleResultPoint(new ResultPoint(
178	          (endRange[0] + endRange[1]) / 2.0f, rowNumber
179	      ));
180	    }
181	
182	
183	    // Make sure there is a quiet zone at least as big as the end pattern after the barcode. The
184	    // spec might want more whitespace, but in practice this is the maximum we can count on.
185	    int end = endRange[1];
186	    int quietEnd = end + (end - endRange[0]);
187	    if (quietEnd >= row.getSize() || !row.isRange(end, quietEnd, false)) {
188	      throw NotFoundException.getNotFoundInstance();
189	    }
190	
191	    String resultString = result.toString();
192	    // UPC/EAN should never be less than 8 chars anyway
193	    if (resultString.length() < 8) {
194	      throw FormatException.getFormatInstance();
195	    }
196	    if (!checkChecksum(resultString)) {
197	      throw ChecksumException.getChecksumInstance();
198	    }
199	
200	    float left = (startGuardRange[1] + startGuardRange[0]) / 2.0f;
201	    float right = (endRange[1] + endRange[0]) / 2.0f;
202	    BarcodeFormat format = getBarcodeFormat();
203	    Result decodeResult = new Result(resultString,
204	        null, // no natural byte representation for these barcodes
205	        new ResultPoint[]{
206	            new ResultPoint(left, rowNumber),
207	            new ResultPoint(right, rowNumber)},
208	        format);
209	
210	    int extensionLength = 0;
211	
212	    try {
213	      Result extensionResult = extensionReader.decodeRow(rowNumber, row, endRange[1]);
214	      decodeResult.putMetadata(ResultMetadataType.UPC_EAN_EXTENSION, extensionResult.getText());
215	      decodeResult.putAllMetadata(extensionResult.getResultMetadata());
216	      decodeResult.addResultPoints(extensionResult.getResultPoints());
217	      extensionLength = extensionResult.getText().length();
218	    } catch (ReaderException re) {
219	      // continue
220	    }
221	
222	    int[] allowedExtensions =
223	        hints == null ? null : (int[]) hints.get(DecodeHintType.ALLOWED_EAN_EXTENSIONS);
224	    if (allowedExtensions != null) {
225	      boolean valid = false;
226	      for (int length : allowedExtensions) {
227	        if (extensionLength == length) {
228	          valid = true;
229	          break;
230	        }
231	      }
232	      if (!valid) {
233	        throw NotFoundException.getNotFoundInstance();
234	      }
235	    }
236	
237	    if (format == BarcodeFormat.EAN_13 || format == BarcodeFormat.UPC_A) {
238	      String countryID = eanManSupport.lookupCountryIdentifier(resultString);
239	      if (countryID != null) {
240	        decodeResult.putMetadata(ResultMetadataType.POSSIBLE_COUNTRY, countryID);
241	      }
242	    }
243	    if (format == BarcodeFormat.EAN_8) {
244	      symbologyIdentifier = 4;
245	    }
246	
247	    decodeResult.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]E" + symbologyIdentifier);
248	
249	    return decodeResult;
250	  }
251	
252	  /**
253	   * @param s string of digits to check
254	   * @return {@link #checkStandardUPCEANChecksum(CharSequence)}
255	   * @throws FormatException if the string does not contain only digits
256	   */
257	  boolean checkChecksum(String s) throws FormatException {
258	    return checkStandardUPCEANChecksum(s);
259	  }
260	
261	  /**
262	   * Computes the UPC/EAN checksum on a string of digits, and reports
263	   * whether the checksum is correct or not.
264	   *
265	   * @param s string of digits to check
266	   * @return true iff string of digits passes the UPC/EAN checksum algorithm
267	   * @throws FormatException if the string does not contain only digits
268	   */
269	  static boolean checkStandardUPCEANChecksum(CharSequence s) throws FormatException {
270	    int length = s.length();
271	    if (length == 0) {
272	      return false;
273	    }
274	    int check = Character.digit(s.charAt(length - 1), 10);
275	    return getStandardUPCEANChecksum(s.subSequence(0, length - 1)) == check;
276	  }
277	
278	  static int getStandardUPCEANChecksum(CharSequence s) throws FormatException {
279	    int length = s.length();
280	    int sum = 0;
281	    for (int i = length - 1; i >= 0; i -= 2) {
282	      int digit = s.charAt(i) - '0';
283	      if (digit < 0 || digit > 9) {
284	        throw FormatException.getFormatInstance();
285	      }
286	      sum += digit;
287	    }
288	    sum *= 3;
289	    for (int i = length - 2; i >= 0; i -= 2) {
290	      int digit = s.charAt(i) - '0';
291	      if (digit < 0 || digit > 9) {
292	        throw FormatException.getFormatInstance();
293	      }
294	      sum += digit;
295	    }
296	    return (1000 - sum) % 10;
297	  }
298	
299	  int[] decodeEnd(BitArray row, int endStart) throws NotFoundException {
300	    return findGuardPattern(row, endStart, false, START_END_PATTERN);
301	  }
302	
303	  static int[] findGuardPattern(BitArray row,
304	                                int rowOffset,
305	                                boolean whiteFirst,
306	                                int[] pattern) throws NotFoundException {
307	    return findGuardPattern(row, rowOffset, whiteFirst, pattern, new int[pattern.length]);
308	  }
309	
310	  /**
311	   * @param row row of black/white values to search
312	   * @param rowOffset position to start search
313	   * @param whiteFirst if true, indicates that the pattern specifies white/black/white/...
314	   * pixel counts, otherwise, it is interpreted as black/white/black/...
315	   * @param pattern pattern of counts of number of black and white pixels that are being
316	   * searched for as a pattern
317	   * @param counters array of counters, as long as pattern, to re-use
318	   * @return start/end horizontal offset of guard pattern, as an array of two ints
319	   * @throws NotFoundException if pattern is not found
320	   */
321	  private static int[] findGuardPattern(BitArray row,
322	                                        int rowOffset,
323	                                        boolean whiteFirst,
324	                                        int[] pattern,
325	                                        int[] counters) throws NotFoundException {
326	    int width = row.getSize();
327	    rowOffset = whiteFirst ? row.getNextUnset(rowOffset) : row.getNextSet(rowOffset);
328	    int counterPosition = 0;
329	    int patternStart = rowOffset;
330	    int patternLength = pattern.length;
331	    boolean isWhite = whiteFirst;
332	    for (int x = rowOffset; x < width; x++) {
333	      if (row.get(x) != isWhite) {
334	        counters[counterPosition]++;
335	      } else {
336	        if (counterPosition == patternLength - 1) {
337	          if (patternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE) < MAX_AVG_VARIANCE) {
338	            return new int[]{patternStart, x};
339	          }
340	          patternStart += counters[0] + counters[1];
341	          System.arraycopy(counters, 2, counters, 0, counterPosition - 1);
342	          counters[counterPosition - 1] = 0;
343	          counters[counterPosition] = 0;
344	          counterPosition--;
345	        } else {
346	          counterPosition++;
347	        }
348	        counters[counterPosition] = 1;
349	        isWhite = !isWhite;
350	      }
351	    }
352	    throw NotFoundException.getNotFoundInstance();
353	  }
354	
355	  /**
356	   * Attempts to decode a single UPC/EAN-encoded digit.
357	   *
358	   * @param row row of black/white values to decode
359	   * @param counters the counts of runs of observed black/white/black/... values
360	   * @param rowOffset horizontal offset to start decoding from
361	   * @param patterns the set of patterns to use to decode -- sometimes different encodings
362	   * for the digits 0-9 are used, and this indicates the encodings for 0 to 9 that should
363	   * be used
364	   * @return horizontal offset of first pixel beyond the decoded digit
365	   * @throws NotFoundException if digit cannot be decoded
366	   */
367	  static int decodeDigit(BitArray row, int[] counters, int rowOffset, int[][] patterns)
368	      throws NotFoundException {
369	    recordPattern(row, rowOffset, counters);
370	    float bestVariance = MAX_AVG_VARIANCE; // worst variance we'll accept
371	    int bestMatch = -1;
372	    int max = patterns.length;
373	    for (int i = 0; i < max; i++) {
374	      int[] pattern = patterns[i];
375	      float variance = patternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE);
376	      if (variance < bestVariance) {
377	        bestVariance = variance;
378	        bestMatch = i;
379	      }
380	    }
381	    if (bestMatch >= 0) {
382	      return bestMatch;
383	    } else {
384	      throw NotFoundException.getNotFoundInstance();
385	    }
386	  }
387	
388	  /**
389	   * Get the format of this decoder.
390	   *
391	   * @return The 1D format.
392	   */
393	  abstract BarcodeFormat getBarcodeFormat();
394	
395	  /**
396	   * Subclasses override this to decode the portion of a barcode between the start
397	   * and end guard patterns.
398	   *
399	   * @param row row of black/white values to search
400	   * @param startRange start/end offset of start guard pattern
401	   * @param resultString {@link StringBuilder} to append decoded chars to
402	   * @return horizontal offset of first pixel after the "middle" that was decoded
403	   * @throws NotFoundException if decoding could not complete successfully
404	   */
405	  protected abstract int decodeMiddle(BitArray row,
406	                                      int[] startRange,
407	                                      StringBuilder resultString) throws NotFoundException;
408	
409	}
