17	package com.google.zxing.oned;
18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.FormatException;
21	import com.google.zxing.NotFoundException;
22	import com.google.zxing.common.BitArray;
23	
24	/**
25	 * <p>Implements decoding of the UPC-E format.</p>
26	 * <p><a href="http://www.barcodeisland.com/upce.phtml">This</a> is a great reference for
27	 * UPC-E information.</p>
28	 *
29	 * @author Sean Owen
30	 */
31	public final class UPCEReader extends UPCEANReader {
32	
33	  /**
34	   * The pattern that marks the middle, and end, of a UPC-E pattern.
35	   * There is no "second half" to a UPC-E barcode.
36	   */
37	  private static final int[] MIDDLE_END_PATTERN = {1, 1, 1, 1, 1, 1};
38	
39	  // For an UPC-E barcode, the final digit is represented by the parities used
40	  // to encode the middle six digits, according to the table below.
41	  //
42	  //                Parity of next 6 digits
43	  //    Digit   0     1     2     3     4     5
44	  //       0    Even   Even  Even Odd  Odd   Odd
45	  //       1    Even   Even  Odd  Even Odd   Odd
46	  //       2    Even   Even  Odd  Odd  Even  Odd
47	  //       3    Even   Even  Odd  Odd  Odd   Even
48	  //       4    Even   Odd   Even Even Odd   Odd
49	  //       5    Even   Odd   Odd  Even Even  Odd
50	  //       6    Even   Odd   Odd  Odd  Even  Even
51	  //       7    Even   Odd   Even Odd  Even  Odd
52	  //       8    Even   Odd   Even Odd  Odd   Even
53	  //       9    Even   Odd   Odd  Even Odd   Even
54	  //
55	  // The encoding is represented by the following array, which is a bit pattern
56	  // using Odd = 0 and Even = 1. For example, 5 is represented by:
57	  //
58	  //              Odd Even Even Odd Odd Even
59	  // in binary:
60	  //                0    1    1   0   0    1   == 0x19
61	  //
62	
63	  /**
64	   * See {@link #L_AND_G_PATTERNS}; these values similarly represent patterns of
65	   * even-odd parity encodings of digits that imply both the number system (0 or 1)
66	   * used, and the check digit.
67	   */
68	  static final int[][] NUMSYS_AND_CHECK_DIGIT_PATTERNS = {
69	      {0x38, 0x34, 0x32, 0x31, 0x2C, 0x26, 0x23, 0x2A, 0x29, 0x25},
70	      {0x07, 0x0B, 0x0D, 0x0E, 0x13, 0x19, 0x1C, 0x15, 0x16, 0x1A}
71	  };
72	
73	  private final int[] decodeMiddleCounters;
74	
75	  public UPCEReader() {
76	    decodeMiddleCounters = new int[4];
77	  }
78	
79	  @Override
80	  protected int decodeMiddle(BitArray row, int[] startRange, StringBuilder result)
81	      throws NotFoundException {
82	    int[] counters = decodeMiddleCounters;
83	    counters[0] = 0;
84	    counters[1] = 0;
85	    counters[2] = 0;
86	    counters[3] = 0;
87	    int end = row.getSize();
88	    int rowOffset = startRange[1];
89	
90	    int lgPatternFound = 0;
91	
92	    for (int x = 0; x < 6 && rowOffset < end; x++) {
93	      int bestMatch = decodeDigit(row, counters, rowOffset, L_AND_G_PATTERNS);
94	      result.append((char) ('0' + bestMatch % 10));
95	      for (int counter : counters) {
96	        rowOffset += counter;
97	      }
98	      if (bestMatch >= 10) {
99	        lgPatternFound |= 1 << (5 - x);
100	      }
101	    }
102	
103	    determineNumSysAndCheckDigit(result, lgPatternFound);
104	
105	    return rowOffset;
106	  }
107	
108	  @Override
109	  protected int[] decodeEnd(BitArray row, int endStart) throws NotFoundException {
110	    return findGuardPattern(row, endStart, true, MIDDLE_END_PATTERN);
111	  }
112	
113	  @Override
114	  protected boolean checkChecksum(String s) throws FormatException {
115	    return super.checkChecksum(convertUPCEtoUPCA(s));
116	  }
117	
118	  private static void determineNumSysAndCheckDigit(StringBuilder resultString, int lgPatternFound)
119	      throws NotFoundException {
120	
121	    for (int numSys = 0; numSys <= 1; numSys++) {
122	      for (int d = 0; d < 10; d++) {
123	        if (lgPatternFound == NUMSYS_AND_CHECK_DIGIT_PATTERNS[numSys][d]) {
124	          resultString.insert(0, (char) ('0' + numSys));
125	          resultString.append((char) ('0' + d));
126	          return;
127	        }
128	      }
129	    }
130	    throw NotFoundException.getNotFoundInstance();
131	  }
132	
133	  @Override
134	  BarcodeFormat getBarcodeFormat() {
135	    return BarcodeFormat.UPC_E;
136	  }
137	
138	  /**
139	   * Expands a UPC-E value back into its full, equivalent UPC-A code value.
140	   *
141	   * @param upce UPC-E code as string of digits
142	   * @return equivalent UPC-A code as string of digits
143	   */
144	  public static String convertUPCEtoUPCA(String upce) {
145	    char[] upceChars = new char[6];
146	    upce.getChars(1, 7, upceChars, 0);
147	    StringBuilder result = new StringBuilder(12);
148	    result.append(upce.charAt(0));
149	    char lastChar = upceChars[5];
150	    switch (lastChar) {
151	      case '0':
152	      case '1':
153	      case '2':
154	        result.append(upceChars, 0, 2);
155	        result.append(lastChar);
156	        result.append("0000");
157	        result.append(upceChars, 2, 3);
158	        break;
159	      case '3':
160	        result.append(upceChars, 0, 3);
161	        result.append("00000");
162	        result.append(upceChars, 3, 2);
163	        break;
164	      case '4':
165	        result.append(upceChars, 0, 4);
166	        result.append("00000");
167	        result.append(upceChars[4]);
168	        break;
169	      default:
170	        result.append(upceChars, 0, 5);
171	        result.append("0000");
172	        result.append(lastChar);
173	        break;
174	    }
175	    // Only append check digit in conversion if supplied
176	    if (upce.length() >= 8) {
177	      result.append(upce.charAt(7));
178	    }
179	    return result.toString();
180	  }
181	
182	}
