17	package com.google.zxing.qrcode.decoder;
18	
19	import com.google.zxing.DecodeHintType;
20	import com.google.zxing.FormatException;
21	import com.google.zxing.common.BitSource;
22	import com.google.zxing.common.CharacterSetECI;
23	import com.google.zxing.common.DecoderResult;
24	import com.google.zxing.common.StringUtils;
25	
26	import java.nio.charset.Charset;
27	import java.util.ArrayList;
28	import java.util.Collection;
29	import java.util.List;
30	import java.util.Map;
31	
32	/**
33	 * <p>QR Codes can encode text as bits in one of several modes, and can use multiple modes
34	 * in one QR Code. This class decodes the bits back into text.</p>
35	 *
36	 * <p>See ISO 18004:2006, 6.4.3 - 6.4.7</p>
37	 *
38	 * @author Sean Owen
39	 */
40	final class DecodedBitStreamParser {
41	
42	  /**
43	   * See ISO 18004:2006, 6.4.4 Table 5
44	   */
45	  private static final char[] ALPHANUMERIC_CHARS =
46	      "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:".toCharArray();
47	  private static final int GB2312_SUBSET = 1;
48	
49	  private DecodedBitStreamParser() {
50	  }
51	
52	  static DecoderResult decode(byte[] bytes,
53	                              Version version,
54	                              ErrorCorrectionLevel ecLevel,
55	                              Map<DecodeHintType,?> hints) throws FormatException {
56	    BitSource bits = new BitSource(bytes);
57	    StringBuilder result = new StringBuilder(50);
58	    List<byte[]> byteSegments = new ArrayList<>(1);
59	    int symbolSequence = -1;
60	    int parityData = -1;
61	    int symbologyModifier;
62	
63	    try {
64	      CharacterSetECI currentCharacterSetECI = null;
65	      boolean fc1InEffect = false;
66	      boolean hasFNC1first = false;
67	      boolean hasFNC1second = false;
68	      Mode mode;
69	      do {
70	        // While still another segment to read...
71	        if (bits.available() < 4) {
72	          // OK, assume we're done. Really, a TERMINATOR mode should have been recorded here
73	          mode = Mode.TERMINATOR;
74	        } else {
75	          mode = Mode.forBits(bits.readBits(4)); // mode is encoded by 4 bits
76	        }
77	        switch (mode) {
78	          case TERMINATOR:
79	            break;
80	          case FNC1_FIRST_POSITION:
81	            hasFNC1first = true; // symbology detection
82	            // We do little with FNC1 except alter the parsed result a bit according to the spec
83	            fc1InEffect = true;
84	            break;
85	          case FNC1_SECOND_POSITION:
86	            hasFNC1second = true; // symbology detection
87	            // We do little with FNC1 except alter the parsed result a bit according to the spec
88	            fc1InEffect = true;
89	            break;
90	          case STRUCTURED_APPEND:
91	            if (bits.available() < 16) {
92	              throw FormatException.getFormatInstance();
93	            }
94	            // sequence number and parity is added later to the result metadata
95	            // Read next 8 bits (symbol sequence #) and 8 bits (parity data), then continue
96	            symbolSequence = bits.readBits(8);
97	            parityData = bits.readBits(8);
98	            break;
99	          case ECI:
100	            // Count doesn't apply to ECI
101	            int value = parseECIValue(bits);
102	            currentCharacterSetECI = CharacterSetECI.getCharacterSetECIByValue(value);
103	            if (currentCharacterSetECI == null) {
104	              throw FormatException.getFormatInstance();
105	            }
106	            break;
107	          case HANZI:
108	            // First handle Hanzi mode which does not start with character count
109	            // Chinese mode contains a sub set indicator right after mode indicator
110	            int subset = bits.readBits(4);
111	            int countHanzi = bits.readBits(mode.getCharacterCountBits(version));
112	            if (subset == GB2312_SUBSET) {
113	              decodeHanziSegment(bits, result, countHanzi);
114	            }
115	            break;
116	          default:
117	            // "Normal" QR code modes:
118	            // How many characters will follow, encoded in this mode?
119	            int count = bits.readBits(mode.getCharacterCountBits(version));
120	            switch (mode) {
121	              case NUMERIC:
122	                decodeNumericSegment(bits, result, count);
123	                break;
124	              case ALPHANUMERIC:
125	                decodeAlphanumericSegment(bits, result, count, fc1InEffect);
126	                break;
127	              case BYTE:
128	                decodeByteSegment(bits, result, count, currentCharacterSetECI, byteSegments, hints);
129	                break;
130	              case KANJI:
131	                decodeKanjiSegment(bits, result, count);
132	                break;
133	              default:
134	                throw FormatException.getFormatInstance();
135	            }
136	            break;
137	        }
138	      } while (mode != Mode.TERMINATOR);
139	
140	      if (currentCharacterSetECI != null) {
141	        if (hasFNC1first) {
142	          symbologyModifier = 4;
143	        } else if (hasFNC1second) {
144	          symbologyModifier = 6;
145	        } else {
146	          symbologyModifier = 2;
147	        }
148	      } else {
149	        if (hasFNC1first) {
150	          symbologyModifier = 3;
151	        } else if (hasFNC1second) {
152	          symbologyModifier = 5;
153	        } else {
154	          symbologyModifier = 1;
155	        }
156	      }
157	
158	    } catch (IllegalArgumentException iae) {
159	      // from readBits() calls
160	      throw FormatException.getFormatInstance();
161	    }
162	
163	    return new DecoderResult(bytes,
164	                             result.toString(),
165	                             byteSegments.isEmpty() ? null : byteSegments,
166	                             ecLevel == null ? null : ecLevel.toString(),
167	                             symbolSequence,
168	                             parityData,
169	                             symbologyModifier);
170	  }
171	
172	  /**
173	   * See specification GBT 18284-2000
174	   */
175	  private static void decodeHanziSegment(BitSource bits,
176	                                         StringBuilder result,
177	                                         int count) throws FormatException {
178	    if (StringUtils.GB2312_CHARSET == null) {
179	      // Not supported without charset support
180	      throw FormatException.getFormatInstance();
181	    }
182	    // Don't crash trying to read more bits than we have available.
183	    if (count * 13 > bits.available()) {
184	      throw FormatException.getFormatInstance();
185	    }
186	
187	    // Each character will require 2 bytes. Read the characters as 2-byte pairs
188	    // and decode as GB2312 afterwards
189	    byte[] buffer = new byte[2 * count];
190	    int offset = 0;
191	    while (count > 0) {
192	      // Each 13 bits encodes a 2-byte character
193	      int twoBytes = bits.readBits(13);
194	      int assembledTwoBytes = ((twoBytes / 0x060) << 8) | (twoBytes % 0x060);
195	      if (assembledTwoBytes < 0x00A00) {
196	        // In the 0xA1A1 to 0xAAFE range
197	        assembledTwoBytes += 0x0A1A1;
198	      } else {
199	        // In the 0xB0A1 to 0xFAFE range
200	        assembledTwoBytes += 0x0A6A1;
201	      }
202	      buffer[offset] = (byte) ((assembledTwoBytes >> 8) & 0xFF);
203	      buffer[offset + 1] = (byte) (assembledTwoBytes & 0xFF);
204	      offset += 2;
205	      count--;
206	    }
207	
208	    result.append(new String(buffer, StringUtils.GB2312_CHARSET));
209	  }
210	
211	  private static void decodeKanjiSegment(BitSource bits,
212	                                         StringBuilder result,
213	                                         int count) throws FormatException {
214	    if (StringUtils.SHIFT_JIS_CHARSET == null) {
215	      // Not supported without charset support
216	      throw FormatException.getFormatInstance();
217	    }
218	    // Don't crash trying to read more bits than we have available.
219	    if (count * 13 > bits.available()) {
220	      throw FormatException.getFormatInstance();
221	    }
222	
223	    // Each character will require 2 bytes. Read the characters as 2-byte pairs
224	    // and decode as Shift_JIS afterwards
225	    byte[] buffer = new byte[2 * count];
226	    int offset = 0;
227	    while (count > 0) {
228	      // Each 13 bits encodes a 2-byte character
229	      int twoBytes = bits.readBits(13);
230	      int assembledTwoBytes = ((twoBytes / 0x0C0) << 8) | (twoBytes % 0x0C0);
231	      if (assembledTwoBytes < 0x01F00) {
232	        // In the 0x8140 to 0x9FFC range
233	        assembledTwoBytes += 0x08140;
234	      } else {
235	        // In the 0xE040 to 0xEBBF range
236	        assembledTwoBytes += 0x0C140;
237	      }
238	      buffer[offset] = (byte) (assembledTwoBytes >> 8);
239	      buffer[offset + 1] = (byte) assembledTwoBytes;
240	      offset += 2;
241	      count--;
242	    }
243	    result.append(new String(buffer, StringUtils.SHIFT_JIS_CHARSET));
244	  }
245	
246	  private static void decodeByteSegment(BitSource bits,
247	                                        StringBuilder result,
248	                                        int count,
249	                                        CharacterSetECI currentCharacterSetECI,
250	                                        Collection<byte[]> byteSegments,
251	                                        Map<DecodeHintType,?> hints) throws FormatException {
252	    // Don't crash trying to read more bits than we have available.
253	    if (8 * count > bits.available()) {
254	      throw FormatException.getFormatInstance();
255	    }
256	
257	    byte[] readBytes = new byte[count];
258	    for (int i = 0; i < count; i++) {
259	      readBytes[i] = (byte) bits.readBits(8);
260	    }
261	    Charset encoding;
262	    if (currentCharacterSetECI == null) {
263	      // The spec isn't clear on this mode; see
264	      // section 6.4.5: t does not say which encoding to assuming
265	      // upon decoding. I have seen ISO-8859-1 used as well as
266	      // Shift_JIS -- without anything like an ECI designator to
267	      // give a hint.
268	      encoding = StringUtils.guessCharset(readBytes, hints);
269	    } else {
270	      encoding = currentCharacterSetECI.getCharset();
271	    }
272	    result.append(new String(readBytes, encoding));
273	    byteSegments.add(readBytes);
274	  }
275	
276	  private static char toAlphaNumericChar(int value) throws FormatException {
277	    if (value >= ALPHANUMERIC_CHARS.length) {
278	      throw FormatException.getFormatInstance();
279	    }
280	    return ALPHANUMERIC_CHARS[value];
281	  }
282	
283	  private static void decodeAlphanumericSegment(BitSource bits,
284	                                                StringBuilder result,
285	                                                int count,
286	                                                boolean fc1InEffect) throws FormatException {
287	    // Read two characters at a time
288	    int start = result.length();
289	    while (count > 1) {
290	      if (bits.available() < 11) {
291	        throw FormatException.getFormatInstance();
292	      }
293	      int nextTwoCharsBits = bits.readBits(11);
294	      result.append(toAlphaNumericChar(nextTwoCharsBits / 45));
295	      result.append(toAlphaNumericChar(nextTwoCharsBits % 45));
296	      count -= 2;
297	    }
298	    if (count == 1) {
299	      // special case: one character left
300	      if (bits.available() < 6) {
301	        throw FormatException.getFormatInstance();
302	      }
303	      result.append(toAlphaNumericChar(bits.readBits(6)));
304	    }
305	    // See section 6.4.8.1, 6.4.8.2
306	    if (fc1InEffect) {
307	      // We need to massage the result a bit if in an FNC1 mode:
308	      for (int i = start; i < result.length(); i++) {
309	        if (result.charAt(i) == '%') {
310	          if (i < result.length() - 1 && result.charAt(i + 1) == '%') {
311	            // %% is rendered as %
312	            result.deleteCharAt(i + 1);
313	          } else {
314	            // In alpha mode, % should be converted to FNC1 separator 0x1D
315	            result.setCharAt(i, (char) 0x1D);
316	          }
317	        }
318	      }
319	    }
320	  }
321	
322	  private static void decodeNumericSegment(BitSource bits,
323	                                           StringBuilder result,
324	                                           int count) throws FormatException {
325	    // Read three digits at a time
326	    while (count >= 3) {
327	      // Each 10 bits encodes three digits
328	      if (bits.available() < 10) {
329	        throw FormatException.getFormatInstance();
330	      }
331	      int threeDigitsBits = bits.readBits(10);
332	      if (threeDigitsBits >= 1000) {
333	        throw FormatException.getFormatInstance();
334	      }
335	      result.append(toAlphaNumericChar(threeDigitsBits / 100));
336	      result.append(toAlphaNumericChar((threeDigitsBits / 10) % 10));
337	      result.append(toAlphaNumericChar(threeDigitsBits % 10));
338	      count -= 3;
339	    }
340	    if (count == 2) {
341	      // Two digits left over to read, encoded in 7 bits
342	      if (bits.available() < 7) {
343	        throw FormatException.getFormatInstance();
344	      }
345	      int twoDigitsBits = bits.readBits(7);
346	      if (twoDigitsBits >= 100) {
347	        throw FormatException.getFormatInstance();
348	      }
349	      result.append(toAlphaNumericChar(twoDigitsBits / 10));
350	      result.append(toAlphaNumericChar(twoDigitsBits % 10));
351	    } else if (count == 1) {
352	      // One digit left over to read
353	      if (bits.available() < 4) {
354	        throw FormatException.getFormatInstance();
355	      }
356	      int digitBits = bits.readBits(4);
357	      if (digitBits >= 10) {
358	        throw FormatException.getFormatInstance();
359	      }
360	      result.append(toAlphaNumericChar(digitBits));
361	    }
362	  }
363	
364	  private static int parseECIValue(BitSource bits) throws FormatException {
365	    int firstByte = bits.readBits(8);
366	    if ((firstByte & 0x80) == 0) {
367	      // just one byte
368	      return firstByte & 0x7F;
369	    }
370	    if ((firstByte & 0xC0) == 0x80) {
371	      // two bytes
372	      int secondByte = bits.readBits(8);
373	      return ((firstByte & 0x3F) << 8) | secondByte;
374	    }
375	    if ((firstByte & 0xE0) == 0xC0) {
376	      // three bytes
377	      int secondThirdBytes = bits.readBits(16);
378	      return ((firstByte & 0x1F) << 16) | secondThirdBytes;
379	    }
380	    throw FormatException.getFormatInstance();
381	  }
