345	      }
346	      int firstByte = bits.readBits(8);
347	      if (firstByte == 254) {  // Unlatch codeword
348	        return;
349	      }
350	
351	      parseTwoBytes(firstByte, bits.readBits(8), cValues);
352	
353	      for (int i = 0; i < 3; i++) {
354	        int cValue = cValues[i];
355	        switch (shift) {
356	          case 0:
357	            if (cValue < 3) {
358	              shift = cValue + 1;
359	            } else if (cValue < TEXT_BASIC_SET_CHARS.length) {
360	              char textChar = TEXT_BASIC_SET_CHARS[cValue];
361	              if (upperShift) {
362	                result.append((char) (textChar + 128));
363	                upperShift = false;
364	              } else {
365	                result.append(textChar);
366	              }
367	            } else {
368	              throw FormatException.getFormatInstance();
369	            }
370	            break;
371	          case 1:
372	            if (upperShift) {
373	              result.append((char) (cValue + 128));
374	              upperShift = false;
375	            } else {
376	              result.append((char) cValue);
377	            }
378	            shift = 0;
379	            break;
380	          case 2:
381	            // Shift 2 for Text is the same encoding as C40
382	            if (cValue < TEXT_SHIFT2_SET_CHARS.length) {
383	              char textChar = TEXT_SHIFT2_SET_CHARS[cValue];
384	              if (upperShift) {
385	                result.append((char) (textChar + 128));
386	                upperShift = false;
387	              } else {
388	                result.append(textChar);
389	              }
390	            } else {
391	              switch (cValue) {
392	                case 27: // FNC1
393	                  fnc1positions.add(result.length());
394	                  result.append((char) 29); // translate as ASCII 29
395	                  break;
396	                case 30: // Upper Shift
397	                  upperShift = true;
398	                  break;
399	                default:
400	                  throw FormatException.getFormatInstance();
401	              }
402	            }
403	            shift = 0;
404	            break;
405	          case 3:
406	            if (cValue < TEXT_SHIFT3_SET_CHARS.length) {
407	              char textChar = TEXT_SHIFT3_SET_CHARS[cValue];
408	              if (upperShift) {
409	                result.append((char) (textChar + 128));
410	                upperShift = false;
411	              } else {
412	                result.append(textChar);
413	              }
414	              shift = 0;
415	            } else {
416	              throw FormatException.getFormatInstance();
417	            }
418	            break;
419	          default:
420	            throw FormatException.getFormatInstance();
421	        }
422	      }
423	    } while (bits.available() > 0);
424	  }
