426	  /**
427	   * See ISO 16022:2006, 5.2.7
428	   */
429	  private static void decodeAnsiX12Segment(BitSource bits,
430	                                           ECIStringBuilder result) throws FormatException {
431	    // Three ANSI X12 values are encoded in a 16-bit value as
432	    // (1600 * C1) + (40 * C2) + C3 + 1
433	
434	    int[] cValues = new int[3];
435	    do {
436	      // If there is only one byte left then it will be encoded as ASCII
437	      if (bits.available() == 8) {
438	        return;
439	      }
440	      int firstByte = bits.readBits(8);
441	      if (firstByte == 254) {  // Unlatch codeword
442	        return;
443	      }
444	
445	      parseTwoBytes(firstByte, bits.readBits(8), cValues);
446	
447	      for (int i = 0; i < 3; i++) {
448	        int cValue = cValues[i];
449	        switch (cValue) {
450	          case 0: // X12 segment terminator <CR>
451	            result.append('\r');
452	            break;
453	          case 1: // X12 segment separator *
454	            result.append('*');
455	            break;
456	          case 2: // X12 sub-element separator >
457	            result.append('>');
458	            break;
459	          case 3: // space
460	            result.append(' ');
461	            break;
462	          default:
463	            if (cValue < 14) {  // 0 - 9
464	              result.append((char) (cValue + 44));
465	            } else if (cValue < 40) {  // A - Z
466	              result.append((char) (cValue + 51));
467	            } else {
468	              throw FormatException.getFormatInstance();
469	            }
470	            break;
471	        }
472	      }
473	    } while (bits.available() > 0);
474	  }
475	
476	  private static void parseTwoBytes(int firstByte, int secondByte, int[] result) {
477	    int fullBitValue = (firstByte << 8) + secondByte - 1;
478	    int temp = fullBitValue / 1600;
479	    result[0] = temp;
480	    fullBitValue -= temp * 1600;
481	    temp = fullBitValue / 40;
482	    result[1] = temp;
483	    result[2] = fullBitValue - temp * 40;
484	  }
485	
486	  /**
487	   * See ISO 16022:2006, 5.2.8 and Annex C Table C.3
488	   */
489	  private static void decodeEdifactSegment(BitSource bits, ECIStringBuilder result) {
490	    do {
491	      // If there is only two or less bytes left then it will be encoded as ASCII
492	      if (bits.available() <= 16) {
493	        return;
494	      }
495	
496	      for (int i = 0; i < 4; i++) {
497	        int edifactValue = bits.readBits(6);
498	
499	        // Check for the unlatch character
